const dict = { ko: ko as Record<string, string>, en: en as Record<string, string> };
export type Vars = Record<string, string | number>;
export type T = (key: Key, vars?: Vars) => string;

const fill = (s: string, v?: Vars) => (v ? s.replace(/\{(\w+)\}/g, (_, k) => String(v[k] ?? `{${k}}`)) : s);

/** Non-hook lookup (controller, toasts). Dynamic keys (`step.${k}`) are template literal types, so a missing key is a type error. */
export const t: T = (key, vars) => {
  const s = dict[get().settings.lang][key] ?? ko[key];
  if (s === undefined && import.meta.env.DEV) console.warn('i18n: missing key', key);
  return fill(s ?? key, vars);
};

export function useT(): T {
  useApp((s) => s.settings.lang); // re-render on language change
  return t;
}

const has = (k: string): k is Key => k in ko;
const isSafari = () => /^((?!chrome|chromium|android).)*safari/i.test(navigator.userAgent);

/** DESIGN 9.10: title, what to do, the message to send to whoever gave the file (only for those codes), and the longer body for "details".
 *  `file` lets the decode error name the real cause for this browser and extension (QA B11). */
export function errText(e: AppError, file?: string): { title: string; body: string; todo?: string; ask?: string } {
  const k = `err.${e.code}` as const;
  const ext = file?.split('.').pop()?.toLowerCase() ?? '';
  const body = e.code === 'AUDIO_DECODE' && isSafari() && ['ogg', 'oga', 'opus', 'webm'].includes(ext) ? t('err.AUDIO_DECODE.safari', { ext }) : t(`${k}.body`);
  const todo = `${k}.do`, ask = `${k}.ask`;
  return { title: t(`${k}.title`), body, todo: has(todo) ? t(todo) : undefined, ask: has(ask) ? t(ask) : undefined };
}
